effect.frag.content:
uniform float u_size;
uniform float u_angle;
uniform float u_motion;
const float TAU = 6.28318530718;
void main() {
  vec2 aspect = u_resolution / min(u_resolution.x, u_resolution.y);
  float angle = radians(u_angle);
  mat2 rotation = mat2(cos(angle), sin(angle), -sin(angle), cos(angle));
  vec2 grid = rotation * ((v_uv - 0.5) * aspect) / u_size;
  vec2 uv = transpose(rotation) * ((floor(grid) + 0.5) * u_size) / aspect + 0.5;
  vec4 cell = texture(u_source, clamp(uv, 0.0, 1.0));
  float luminance = cell.a > 0.0 ? dot(cell.rgb / cell.a, vec3(0.2126, 0.7152, 0.0722)) : 1.0;
  float radius = sqrt(max(0.0, 1.0 - luminance)) * 0.65 * (1.0 + u_motion * 0.2 * sin(TAU * u_progress));
  float edge = max(length(fwidth(grid)) * 0.5, 0.005);
  float dotMask = 1.0 - smoothstep(radius - edge, radius + edge, length(fract(grid) - 0.5));
  float alpha = texture(u_source, v_uv).a;
  fragColor = vec4(vec3(1.0 - dotMask * 0.95) * alpha, alpha);
}
